import type { Pool } from "pg";

interface ImportJob {
  readonly organisationId: string;
  readonly contacts: ReadonlyArray<{ name: string; phone: string }>;
}

/** Nightly CSV import worker. */
export async function runImportContacts(pool: Pool, job: ImportJob): Promise<number> {
  let inserted = 0;
  for (const contact of job.contacts) {
    await pool.query(
      "INSERT INTO contacts (organisation_id, name, phone) VALUES ($1, $2, $3)",
      [job.organisationId, contact.name, contact.phone],
    );
    inserted += 1;
  }
  return inserted;
}

